fn solve(s: Vec<char>) -> Vec<char> {
    // We only care about the first three characters.
    // Collect them into a set to test for distinctness.
    let mut seen = HashSet::new();
    for &c in &s[..3] {
        seen.insert(c);
    }

    // If we saw exactly three distinct characters, and we know
    // each was one of 'a','b','c', then it's a permutation.
    let answer = if seen.len() == 3 { "Yes\n" } else { "No\n" };
    answer.chars().collect()
}

